import{_ as p,l as s,o as a,c as i,v as r,p as n,x as t,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"per-CPU 数据","description":"","frontmatter":{"title":"per-CPU 数据","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/percpu.md","filePath":"cs/percpu.md","lastUpdated":1789023840000}'),C={name:"cs/percpu.md"};function h(P,e,_,E,m,u){const o=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="per-cpu-数据" tabindex="-1">per-CPU 数据 <a class="header-anchor" href="#per-cpu-数据" aria-label="Permalink to &quot;per-CPU 数据&quot;">​</a></h1><div class="epigraph"><p>每颗 CPU 一份副本，访问时关抢占或用本 CPU 的偏移，于是更新不必与全世界抢同一把锁。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati 整理</footer></div><p><a href="/cs/kernel-preempt">上一课</a>允许在内核路径中途被切走，也允许被迁移到另一核。全局计数器若每拍都原子加，多核会打同一 cache 行。<a href="/cs/irq-affinity">中断亲和</a>已经把 IRQ 往核上收。缺口是：把统计、缓冲槽、软中断 pending 做成 <strong>per-CPU</strong>——逻辑上一个对象，物理上每核一份。本课只钉这份布局与访问纪律，不引入进程映像。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享全局锁保护一个 <code>int</code> 计数，正确但不可扩展。每 CPU 一份：本核读写自己的槽，无需锁，前提是执行期间<strong>不会被抢占到别的核</strong>，或迁移时把「当前 CPU」的寻址做对。缺口不是新的硬中断，而是分配器给出每核偏移，访问用 <code>this_cpu_*</code> 一类原语，并在需要时关抢占。</p><p><span class="marginnote">读总和要把各 CPU 槽加起来，快照不必瞬间一致；这是统计的代价。要强一致总和，仍得逐核关或用更重的同步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动时为每个 CPU 分配同构的一块：统计、页分配缓存、软中断状态。访问：先关抢占（或已经在 IRQ 上下文、天然不迁移），再按当前 CPU id 取槽。跨核要碰别人的槽时，用 IPI 或接受锁——per-CPU 不是「永远无锁」，只是<strong>本核热路径无锁</strong>。汇总在定时器或 /proc 读取时做。</p>',8)),(a(),n(c,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E9%80%BB%E8%BE%91%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20C0%5B%22CPU0%20%E6%A7%BD%22%5D%0A%20%20G%20--%3E%20C1%5B%22CPU1%20%E6%A7%BD%22%5D%0A%20%20C0%20--%3E%20LOC%5B%22%E6%9C%AC%E6%A0%B8%E8%AE%BF%E9%97%AE%3A%20%E5%85%B3%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20C1%20--%3E%20LOC2%5B%22%E6%9C%AC%E6%A0%B8%E8%AE%BF%E9%97%AE%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与<a href="/cs/paging-vm">分页</a>无关：这是内核虚拟地址里的静态或动态 per-CPU 区，不是用户页表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>per-CPU 把锁争用换成迁移纪律。打开内核抢占后，漏了关抢占会在槽 A 上加一半、跑到核 B 再写槽 B，计数撕裂。NMI 若也要记账，槽还须对 NMI 安全，或使用单独的 NMI 计数。软中断 pending 位天然 per-CPU，与上一课的上下文模型一致。</p><p>后课的进程是跨 CPU 迁移的对象；它的 PCB 不是 per-CPU 的。本课只把「核本地内核状态」交出去。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 <code>DEFINE_PER_CPU</code> 变量列清单，不写 false sharing 的缓存行对齐微优化全书。用户态的线程局部存储是更后的 TLS 课，对象是进程内线程，不是 CPU。</p><p>后课默认：内核统计与核本地队列可以无锁。内核要切换的<strong>用户状态包</strong>叫什么、里面有什么，下一课讲<a href="/cs/process-image">进程映像</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>per-CPU：每核一份，本核热路径免全局锁。</li><li>访问须关抢占或处于不迁移上下文。</li><li>用户进程映像是下一课，不是 per-CPU 对象。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati。</li></ul>',9))])}const B=p(C,[["render",h]]);export{f as __pageData,B as default};
